import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


REQUIRED_FIELDS = [
    "VendorName",
    "InvoiceReceiptDate",
    "Total",
]


def _confidence_from_field(field: Any) -> Optional[float]:
    if field is None:
        return None
    if isinstance(field, dict):
        for key in ("Confidence", "confidence", "score", "Score"):
            if key in field:
                try:
                    return float(field[key])
                except (TypeError, ValueError):
                    return None
        value = field.get("ValueDetection") or field.get("Value")
        if isinstance(value, dict):
            for key in ("Confidence", "confidence", "score", "Score"):
                if key in value:
                    try:
                        return float(value[key])
                    except (TypeError, ValueError):
                        return None
    return None


def _extract_expense_field_map(analyze_response: Dict[str, Any]) -> Dict[str, Any]:
    expense_documents = analyze_response.get("ExpenseDocuments") or []
    if not expense_documents:
        return {}
    summary_fields = expense_documents[0].get("SummaryFields") or []
    field_map: Dict[str, Any] = {}
    for item in summary_fields:
        if not isinstance(item, dict):
            continue
        field_type = item.get("Type") or {}
        if isinstance(field_type, dict):
            label = field_type.get("Text") or field_type.get("Name")
        else:
            label = None
        if not label:
            continue
        field_map[label] = item
    return field_map


def validate_invoice_structure(
    document_bytes: bytes,
    required_fields: Optional[List[str]] = None,
    min_confidence: float = 0.80,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Validates required structured invoice fields and confidence scores using Amazon Textract AnalyzeExpense.

    Returns:
        {
            "valid": bool,
            "missing_fields": [...],
            "low_confidence_fields": [{"field": str, "confidence": float}],
            "fields": {field_name: {"value": str, "confidence": float}}
        }
    """
    required_fields = required_fields or REQUIRED_FIELDS
    region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION") or "us-east-1"

    client = boto3.client("textract", region_name=region_name)

    try:
        response = client.analyze_expense(Document={"Bytes": document_bytes})
    except (BotoCoreError, ClientError) as exc:
        return {
            "valid": False,
            "error": str(exc),
            "missing_fields": required_fields[:],
            "low_confidence_fields": [],
            "fields": {},
        }

    field_map = _extract_expense_field_map(response)

    missing_fields: List[str] = []
    low_confidence_fields: List[Dict[str, Any]] = []
    extracted_fields: Dict[str, Dict[str, Any]] = {}

    for field_name in required_fields:
        raw_field = field_map.get(field_name)
        if not raw_field:
            missing_fields.append(field_name)
            continue

        value = None
        if isinstance(raw_field, dict):
            value_detection = raw_field.get("ValueDetection") or {}
            if isinstance(value_detection, dict):
                value = value_detection.get("Text") or value_detection.get("NormalizedValue", {}).get("Value")
            if value is None:
                value = raw_field.get("Text")

        confidence = _confidence_from_field(raw_field) or 0.0
        extracted_fields[field_name] = {"value": value, "confidence": confidence}

        if confidence < min_confidence:
            low_confidence_fields.append({"field": field_name, "confidence": confidence})

    valid = not missing_fields and not low_confidence_fields

    return {
        "valid": valid,
        "missing_fields": missing_fields,
        "low_confidence_fields": low_confidence_fields,
        "fields": extracted_fields,
        "raw_response": response,
    }
